test("period by due by scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "7");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20"}));
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-01", "to": "2026-03-28"})).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-03-28", "note": "n"}));
  expect(await ui.statementAsOf(pg_uma, p_cam, "2026-02-10")).toBe(false);
  const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "99.95", "date": "2026-02-10"}));
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
